    def _initialize_crew_batch(self, source: Any, event: BaseEvent) -> None:
        """Initialize trace batch.

        Args:
            source: Source object that triggered the event.
            event: Event object containing crew information.
        """
        user_context = self._get_user_context()
        execution_metadata = {
            "crew_name": getattr(event, "crew_name", "Unknown Crew"),
            "execution_start": event.timestamp,
            "crewai_version": get_crewai_version(),
        }

        self.batch_manager.batch_owner_type = "crew"
        self.batch_manager.batch_owner_id = getattr(source, "id", str(uuid.uuid4()))

        self._initialize_batch(user_context, execution_metadata)

    def _initialize_flow_batch(self, source: Any, event: BaseEvent) -> None:
        """Initialize trace batch for Flow execution.

        Args:
            source: Source object that triggered the event.
            event: Event object containing flow information.
        """
        user_context = self._get_user_context()
        execution_metadata = {
            "flow_name": getattr(event, "flow_name", "Unknown Flow"),
            "execution_start": event.timestamp,
            "crewai_version": get_crewai_version(),
            "execution_type": "flow",
        }

        self.batch_manager.batch_owner_type = "flow"
        self.batch_manager.batch_owner_id = getattr(source, "id", str(uuid.uuid4()))

        self._initialize_batch(user_context, execution_metadata)

    def _initialize_batch(
        self, user_context: dict[str, str], execution_metadata: dict[str, Any]
    ) -> None:
        """Initialize trace batch - auto-enable ephemeral for first-time users.

        Args:
            user_context: User context information.
            execution_metadata: Metadata about the execution.
        """
        if self.first_time_handler.is_first_time:
            self.batch_manager.initialize_batch(
                user_context, execution_metadata, use_ephemeral=True
            )
            return

        use_ephemeral = not self._check_authenticated()
        self.batch_manager.initialize_batch(
            user_context, execution_metadata, use_ephemeral=use_ephemeral
        )

    def _handle_trace_event(self, event_type: str, source: Any, event: Any) -> None:
        """Generic handler for context end events.

        Args:
            event_type: Type of the event.
            source: Source object that triggered the event.
            event: Event object.
        """
        self.batch_manager.begin_event_processing()
        try:
            trace_event = self._create_trace_event(event_type, source, event)
            self.batch_manager.add_event(trace_event)
        finally:
            self.batch_manager.end_event_processing()

    def _handle_action_event(self, event_type: str, source: Any, event: Any) -> None:
        """Generic handler for action events (LLM calls, tool usage).

        Args:
            event_type: Type of the event.
            source: Source object that triggered the event.
            event: Event object.
        """
        if not self.batch_manager.is_batch_initialized():
            user_context = self._get_user_context()
            execution_metadata = {
                "crew_name": getattr(source, "name", "Unknown Crew"),
                "crewai_version": get_crewai_version(),
            }
            self._initialize_batch(user_context, execution_metadata)

        self.batch_manager.begin_event_processing()
        try:
            trace_event = self._create_trace_event(event_type, source, event)
            self.batch_manager.add_event(trace_event)
        finally:
            self.batch_manager.end_event_processing()

    def _create_trace_event(
        self, event_type: str, source: Any, event: BaseEvent
    ) -> TraceEvent:
        """Create a trace event with ordering information."""
        trace_event = TraceEvent(
            type=event_type,
            timestamp=event.timestamp.isoformat() if event.timestamp else "",
            event_id=event.event_id,
            emission_sequence=event.emission_sequence,
            parent_event_id=event.parent_event_id,
            previous_event_id=event.previous_event_id,
            triggered_by_event_id=event.triggered_by_event_id,
        )

        trace_event.event_data = self._build_event_data(event_type, event, source)

        return trace_event

    def _build_event_data(
        self, event_type: str, event: Any, source: Any
    ) -> dict[str, Any]:
        """Build event data"""
        if event_type not in self.complex_events:
            return safe_serialize_to_dict(event)
        if event_type == "task_started":
            task_name = event.task.name or event.task.description
            task_display_name = (
                task_name[:80] + "..." if len(task_name) > 80 else task_name
            )
            return {
                "task_description": event.task.description,
                "expected_output": event.task.expected_output,
                "task_name": task_name,
                "task_display_name": task_display_name,
                "context": event.context,
                "agent_role": source.agent.role,
                "task_id": str(event.task.id),
            }
        if event_type == "task_completed":
            return {
                "task_description": event.task.description if event.task else None,
                "task_name": event.task.name or event.task.description
                if event.task
                else None,
                "task_id": str(event.task.id) if event.task else None,
                "output_raw": event.output.raw if event.output else None,
                "output_format": str(event.output.output_format)
                if event.output
                else None,
                "agent_role": event.output.agent if event.output else None,
            }
        if event_type == "agent_execution_started":
            return {
                "agent_role": event.agent.role,
                "agent_goal": event.agent.goal,
                "agent_backstory": event.agent.backstory,
            }
        if event_type == "agent_execution_completed":
            return {
                "agent_role": event.agent.role,
                "agent_goal": event.agent.goal,
                "agent_backstory": event.agent.backstory,
            }
        if event_type == "llm_call_started":
            event_data = safe_serialize_to_dict(event)
            event_data["task_name"] = event.task_name or getattr(
                event, "task_description", None
            )
            return event_data
        if event_type == "llm_call_completed":
            return safe_serialize_to_dict(event)

        return {
            "event_type": event_type,
            "event": safe_serialize_to_dict(event),
            "source": source,
        }

    def _show_tracing_disabled_message(self) -> None:
        """Show a message when tracing is disabled."""
        from rich.console import Console
        from rich.panel import Panel

        from crewai.events.listeners.tracing.utils import (
            has_user_declined_tracing,
            should_suppress_tracing_messages,
        )

        if should_suppress_tracing_messages():
            return

        console = Console()

        if has_user_declined_tracing():
            message = """Info: Tracing is disabled.

To enable tracing, do any one of these:
• Set tracing=True in your Crew/Flow code
• Set CREWAI_TRACING_ENABLED=true in your project's .env file
• Run: crewai traces enable"""
        else:
            message = """Info: Tracing is disabled.

To enable tracing, do any one of these:
• Set tracing=True in your Crew/Flow code
• Set CREWAI_TRACING_ENABLED=true in your project's .env file
• Run: crewai traces enable"""

        panel = Panel(
            message,
            title="Tracing Status",
            border_style="blue",
            padding=(1, 2),
        )
        console.print(panel)

def should_suppress_tracing_messages() -> bool:
    """Check if tracing messages should be suppressed.

    Returns:
        True if messages should be suppressed, False otherwise.
    """
    return _suppress_tracing_messages.get()

def _load_user_data() -> dict[str, Any]:
    p = _user_data_file()
    if p.exists():
        try:
            return cast(dict[str, Any], json.loads(p.read_text()))
        except (json.JSONDecodeError, OSError, PermissionError) as e:
            logger.warning(f"Failed to load user data: {e}")
    return {}

def _user_data_lock_name() -> str:
    """Return a stable lock name for the user data file."""
    return f"file:{os.path.realpath(_user_data_file())}"

def on_first_execution_tracing_confirmation() -> bool:
    if _is_test_environment():
        return False

    if is_first_execution():
        mark_first_execution_done()
        return click.confirm(
            "This is the first execution of CrewAI. Do you want to enable tracing?",
            default=True,
            show_default=True,
        )
    return False

def _is_test_environment() -> bool:
    """Detect if we're running in a test environment."""
    return os.environ.get("CREWAI_TESTING", "").lower() == "true"

def _get_machine_id() -> str:
    """Stable, privacy-preserving machine fingerprint (cross-platform)."""
    parts = []

    try:
        mac = ":".join(
            [f"{(uuid.getnode() >> b) & 0xFF:02x}" for b in range(0, 12, 2)][::-1]
        )
        parts.append(mac)
    except Exception:  # noqa: S110
        pass

    try:
        sysname = platform.system()
        parts.append(sysname)
    except Exception:
        sysname = "unknown"
        parts.append(sysname)

    try:
        if sysname == "Darwin":
            try:
                res = subprocess.run(
                    ["/usr/sbin/system_profiler", "SPHardwareDataType"],
                    capture_output=True,
                    text=True,
                    timeout=2,
                )
                m = re.search(r"Hardware UUID:\s*([A-Fa-f0-9\-]+)", res.stdout)
                if m:
                    parts.append(m.group(1))
            except Exception:  # noqa: S110
                pass

        elif sysname == "Linux":
            linux_id = _get_linux_machine_id()
            if linux_id:
                parts.append(linux_id)

        elif sysname == "Windows":
            try:
                res = subprocess.run(
                    [
                        "C:\\Windows\\System32\\wbem\\wmic.exe",
                        "csproduct",
                        "get",
                        "UUID",
                    ],
                    capture_output=True,
                    text=True,
                    timeout=2,
                )
                lines = [
                    line.strip() for line in res.stdout.splitlines() if line.strip()
                ]
                if len(lines) >= 2:
                    parts.append(lines[1])
            except Exception:  # noqa: S110
                pass
        else:
            generic_id = _get_generic_system_id()
            if generic_id:
                parts.append(generic_id)

    except Exception:  # noqa: S110
        pass

    if len(parts) <= 1:
        try:
            import socket

            parts.append(socket.gethostname())
        except Exception:  # noqa: S110
            pass

        try:
            parts.append(getpass.getuser())
        except Exception:  # noqa: S110
            pass

        try:
            parts.append(platform.machine())
            parts.append(platform.processor())
        except Exception:  # noqa: S110
            pass

    if not parts:
        parts.append("unknown-system")
        parts.append(str(uuid.uuid4()))

    return hashlib.sha256("".join(parts).encode()).hexdigest()

def _get_generic_system_id() -> str | None:
    try:
        parts = []

        try:
            import socket

            hostname = socket.gethostname()
            if hostname:
                parts.append(hostname)
        except Exception:  # noqa: S110
            pass

        try:
            parts.append(platform.machine())
            parts.append(platform.processor())
            parts.append(platform.architecture()[0])
        except Exception:  # noqa: S110
            pass

        try:
            container_id = os.environ.get(
                "HOSTNAME", os.environ.get("CONTAINER_ID", "")
            )
            if container_id:
                parts.append(container_id)
        except Exception:  # noqa: S110
            pass

        if parts:
            return "-".join(filter(None, parts))

    except Exception:  # noqa: S110
        pass

    return None

def _generate_user_id() -> str:
    """Compute an anonymized user identifier from username and machine ID."""
    try:
        username = getpass.getuser()
    except Exception:
        username = "unknown"

    seed = f"{username}|{_get_machine_id()}"
    return hashlib.sha256(seed.encode()).hexdigest()

def is_first_execution() -> bool:
    """True if this is the first execution for this user."""
    data = _load_user_data()
    return not data.get("first_execution_done", False)

def safe_serialize_to_dict(obj: Any, exclude: set[str] | None = None) -> dict[str, Any]:
    """Safely serialize an object to a dictionary for event data."""
    try:
        serialized = to_serializable(obj, exclude)
        if isinstance(serialized, dict):
            return serialized
        return {"serialized_data": serialized}
    except Exception as e:
        return {"serialization_error": str(e), "object_type": type(obj).__name__}

def truncate_messages(
    messages: list[dict[str, Any]], max_content_length: int = 500, max_messages: int = 5
) -> list[dict[str, Any]]:
    """Truncate message content and limit number of messages"""
    if not messages or not isinstance(messages, list):
        return messages

    limited_messages = messages[:max_messages]

    for msg in limited_messages:
        if isinstance(msg, dict) and "content" in msg:
            content = msg["content"]
            if len(content) > max_content_length:
                msg["content"] = content[:max_content_length] + "..."

    return limited_messages

def should_auto_collect_first_time_traces() -> bool:
    """True if we should auto-collect traces for first-time user.

    Returns:
        True if first-time user AND telemetry not disabled AND tracing not explicitly enabled, False otherwise.
    """
    hook = _first_time_trace_hook.get()
    if hook is not None:
        return hook()

    if _is_test_environment():
        return False

    # If user has previously declined, never auto-collect
    if has_user_declined_tracing():
        return False

    if is_tracing_enabled_in_context():
        return False

    return is_first_execution()

def _is_interactive_terminal() -> bool:
    """Check if stdin is an interactive terminal.

    Returns False in non-interactive contexts (CI, API servers, Docker, etc.)
    to avoid blocking on prompts that no one can respond to.
    """
    import sys

    try:
        stdin = getattr(sys, "stdin", None)
        if stdin is None:
            return False
        isatty = getattr(stdin, "isatty", None)
        if not callable(isatty):
            return False
        return bool(isatty())
    except Exception:
        return False

def get_input() -> None:
    try:
        response = input().strip().lower()
        result[0] = response in ["y", "yes"]
    except (EOFError, KeyboardInterrupt, OSError, LookupError):
        # Handle all input-related errors silently
        result[0] = False

