def _flatten_slots(slots: list[DayOpeningHours]) -> list[dict[str, str]]:
    """Convert a list of DayOpeningHours dicts into simplified entries."""
    return [
        {
            "day": slot["full_name"].lower(),
            "opens": slot["opens"],
            "closes": slot["closes"],
        }
