        self,
        **kwargs: Any,
    ) -> Any:
        directory: str | None = kwargs.get("directory", self.directory)
        if directory is None:
            raise ValueError("Directory must be provided.")

        directory = validate_directory_path(directory)
        if directory[-1] == "/":
            directory = directory[:-1]
