def _is_crewai_dep(spec: str) -> bool:
    """Return True if *spec* is a ``crewai`` or ``crewai[...]`` dependency."""
    if not spec.startswith("crewai"):
        return False
    rest = spec[6:]
    return len(rest) > 0 and rest[0] in ("[", "=", ">", "<", "~", "!")

